window.TAKAMUL_KB = {"version":1,"pages":[{"id":"index","url":"index.html","title":"الرئيسية","icon":"home"},{"id":"about","url":"about.html","title":"من نحن","icon":"info"},{"id":"initiatives","url":"initiatives.html","title":"المبادرات","icon":"sprout"},{"id":"expansion","url":"expansion.html","title":"خطة التوسع","icon":"globe"},{"id":"governance","url":"governance.html","title":"الحوكمة والتمويل","icon":"shield"},{"id":"join","url":"join.html","title":"العضوية","icon":"users"},{"id":"faq","url":"faq.html","title":"دليل الإجابات","icon":"help"},{"id":"dashboard","url":"dashboard.html","title":"لوحة القيادة","icon":"chart"}],"items":[{"id":"s1","type":"section","num":"1","title":"الهوية والمقر والأحكام العامة","subtitle":"من نحن، وأين نعمل","text":"جمعية تكامل لبناء القيم والتنمية مؤسسة أهلية مستقلة غير ربحية، مسجّلة وفق أحكام القانون، تسعى إلى بناء الإنسان وتعزيز منظومة القيم الأخلاقية والاجتماعية ودعم التنمية المستدامة عبر مشاريع نوعية ومبتكرة.\nالاسم الرسمي\nجمعية تكامل لبناء القيم والتنمية – مؤسسة أهلية مسجلة ذات نطاق عمل مجتمعي وتنموي شامل\nالمقر الرئيسي\nمدينة إسطنبول، الجمهورية التركية\nنطاق العمل\nمحلي ودولي؛ يحق للجمعية افتتاح فروع ومكاتب تمثيلية داخل تركيا وخارجها وفق خطة التوسع المعتمدة","url":"about.html#s1","page":"about.html","section":1,"group":""},{"id":"s2","type":"section","num":"2","title":"الرؤية والرسالة والأهداف الإستراتيجية","subtitle":"إلى أين نتجه، وكيف نصل","text":"الرؤية\nأن نكون المؤسسة الرائدة عالمياً في بناء القيم وترسيخ البناء الأخلاقي وتعزيز التنسيق والشراكة بين منظمات المجتمع المدني، وتحقيق تنمية مجتمعية واقتصادية شاملة ومستدامة للمجتمعات والأسر والأفراد بحلول عام 2035.\nالرسالة\nترسيخ القيم الأخلاقية والمهارية لدى الأفراد والمؤسسات، واستثمار الطاقات البشرية عبر برامج قيمية وتكاملية، وتفعيل الشراكات مع الجمعيات التركية وجمعيات الجاليات، وإطلاق مبادرات تنموية وإنتاجية نموذجية تحقق الاستقرار والازدهار وتوفر فرص العمل.\n2.1  الأهداف الإستراتيجية\n1\nتعزيز القيم الإيجابية\nترسيخ القيم الأخلاقية والإنسانية والوسطية في المجتمع، وبناء أجيال ذات مرجعية قيمية راسخة.\n2\nالتمكين والتأهيل\nإكساب الشباب والأسر والنساء المهارات الحياتية والاقتصادية الحديثة والتأهيل المهني.\n3\nالتكامل والتنسيق المؤسسي\nالربط بين الجمعيات التركية وجمعيات الجاليات لتفادي تكرار الجهود وتبادل الخبرات وتعظيم الاستفادة من الموارد.\n4\nمساندة التنمية والجهود الرسمية\nدعم جهود الدولة في توفير فرص العمل والتأهيل المهني والحد من التحديات الاقتصادية والبطالة.\n5\nالاستدامة والحلول الشاملة\nتقديم حلول تنموية واجتماعية واقتصادية قائمة على الشراكات الإستراتيجية والاستثمار الاجتماعي.","url":"about.html#s2","page":"about.html","section":2,"group":""},{"id":"s3","type":"section","num":"3","title":"المبادرات التنموية الرئيسية ومحاور العمل","subtitle":"مبادرتان تنمويتان ومحور مساند","text":"تحقق الجمعية أهدافها الميدانية والتعليمية من خلال مبادرتين تنمويتين رئيسيتين، يدعمهما محور للتنسيق والتكامل المؤسسي.\n3.1  مبادرة «ينابيع» – البناء الفكري والقيمي والتربية التفاعلية\nمجال التركيز: التربية القيمية، والبناء الفكري، والتواصل الثقافي والمجتمعي والتكيف.\nتقديم المناهج والورش القيمية والأخلاقية للأطفال والشباب والناشئة.\nبرامج الإرشاد الأسري والتربوي والتطوير الشخصي لبناء أسر متماسكة.\nتعزيز التكيف الثقافي والتعايش المجتمعي عبر لقاءات حوارية وفعاليات ثقافية.\nملتقيات شبابية وبرامج توعوية لحماية النشء من السلوكيات الضارة.\n3.2  مبادرة «منافع» – التكافل والتضامن والتمكين الاقتصادي\nمجال التركيز: معالجة التحديات الاقتصادية، والتمكين الاقتصادي، والتوظيف، والتكافل والتضامن.\nالتأهيل والتدريب المهني للشباب والنساء مساندةً لخطط الدولة في توفير فرص العمل.\nمنصات وشبكات تربط الكفاءات والعمالة الماهرة بسوق العمل ومؤسسات الإنتاج.\nدعم وتمويل المشاريع الصغرى والأسر المنتجة لتحقيق الاكتفاء الذاتي.\nأنشطة التكافل الاجتماعي والمساعدات غير المباشرة للأسر المتعففة.\n3.3  محور التنسيق والتكامل المؤسسي والأنشطة المساندة\nتكامل الموارد\nالربط بين الجمعيات التركية وجمعيات الجاليات لإقامة أنشطة مشتركة وتكامل الخدمات.\nالدعم التقني\nتقديم الدعم التقني والتأهيل التنموي للفئات المستضعفة والمحتاجة.\nالأبحاث والدراسات\nدراسات ميدانية حول سوق العمل والواقع المجتمعي، وإصدار الحقائب والمجلات التوعوية.\nالصلاحية العامة\nممارسة الأنشطة الاجتماعية والثقافية والتعليمية والاقتصادية والرياضية، وتأسيس منشآت اقتصادية، والاستفادة من المنح، وتوقيع بروتوكولات التعاون.","url":"initiatives.html#s3","page":"initiatives.html","section":3,"group":""},{"id":"s4","type":"section","num":"4","title":"فلسفة العمل والأقسام التنفيذية","subtitle":"المبادئ التي نعمل بها، والفرق التي تنفّذ","text":"4.1  فلسفة العمل\nالتكامل والربط\nSynergy\nتنسيق فاعل بين الجمعيات الأهلية لبناء شراكات مثمرة واستثمار الموارد بكفاءة.\nالتمكين والديمومة\nEmpowerment\nالانتقال من الإغاثة المباشرة إلى التأهيل المهني والتمكين الإنتاجي المستدام.\nالأثر المزدوج\nDual Impact\nجمع متوازن بين البناء القيمي (ينابيع) والتمكين الاقتصادي والاجتماعي (منافع).\nالاستدامة الذاتية\nSelf-Sustainability\nتشغيل استثماري واجتماعي يضمن موارد ثابتة لتمويل البرامج.\n4.2  الأقسام التنفيذية داخل الجمعية\nالقسم\nالمهام الرئيسية\nقسم البرامج القيمية والتربوية\nإعداد البرامج التربوية والمناهج القيمية لمبادرة «ينابيع» وتطبيقها.\nقسم التنسيق والعلاقات بين الجمعيات\nبناء شبكة العلاقات المؤسسية والأنشطة المشتركة بين الجمعيات.\nقسم التأهيل المهني والتوظيف\nإدارة دورات التدريب المهني ومنصات التوظيف والمشاريع الصغرى ضمن «منافع».\nقسم التكافل والتضامن الاجتماعي\nالمسح الميداني والدعم الاجتماعي المباشر للأسر والطلاب.\nقسم الدراسات والتخطيط والاستثمار الاجتماعي\nالبحث الميداني ومتابعة جودة الأداء وإدارة المطبوعات وتشغيل المنشآت الاقتصادية.","url":"about.html#s4","page":"about.html","section":4,"group":""},{"id":"s5","type":"section","num":"5","title":"البرنامج الزمني للتوسع الجغرافي","subtitle":"خطة مرحلية محسوبة تضمن الجودة ونقل الخبرة","text":"المرحلة\n1\nإسطنبول\nالتأسيس وبناء النموذج التشغيلي المعياري واختبار المبادرات.\nالمرحلة\n2\nأنقرة\nتعزيز الحضور في العاصمة وبناء الشراكات المركزية مع المؤسسات الرسمية.\nالمرحلة\n3\nأكبر 10 ولايات تركية\nنشر النموذج وتغطية الكثافات السكانية الكبرى عبر فروع ومكاتب تمثيلية.\nالمرحلة\n4\nكافة الولايات التركية\nتحقيق التغطية الوطنية الشاملة.\nالمرحلة\n5\nأهم 10 دول إسلامية\nنقل التجربة وتأسيس شراكات إقليمية لتصدير الحقائب القيمية والتنموية.\nالمرحلة\n6\nباقي الدول الإسلامية\nتعميق الأثر وتفعيل التكافل والتكامل التنموي الإسلامي.\nالمرحلة\n7\nالدول ذات الأهمية العالمية\nالتواصل مع الجاليات والمجتمعات العالمية وبناء نموذج عمل إنساني وقيمي عالمي.","url":"expansion.html#s5","page":"expansion.html","section":5,"group":""},{"id":"s6","type":"section","num":"6","title":"الفئات والمؤسسات المستهدفة","subtitle":"لمن نعمل","text":"الجمعيات والمنظمات الأهلية\nالتنسيق وتكامل الموارد والخبرات والأنشطة المشتركة.\nالشباب والباحثون عن عمل\nالتأهيل المهني والتدريب والربط بسوق العمل والتوظيف.\nالأسر والأطفال والنساء\nالبناء القيمي والإرشاد الأسري والتمكين الإنتاجي.\nمؤسسات الدولة والمجتمع\nالشراكة الاقتصادية والاجتماعية ومساندة خطط التنمية.","url":"initiatives.html#s6","page":"initiatives.html","section":6,"group":""},{"id":"s7","type":"section","num":"7","title":"الحوكمة والإدارة وإجراءات العمل","subtitle":"الهيكل التنظيمي وآليات اتخاذ القرار","text":"7.1  الهيكل الإداري والحوكمة المؤسسية\nجميع الأعضاء\nالجمعية العمومية\nGenel Kurul\nالسلطة العليا في الجمعية؛ تجتمع اجتماعاً عادياً كل 3 سنوات في شهر أبريل، وتختص بتعديل النظام الأساسي وإقرار السياسات العامة والتصويت.\n5 + 5\nمجلس الإدارة\nYönetim Kurulu\n5 أعضاء أساسيين و5 احتياط. السلطة التنفيذية الممثلة للجمعية: يدير الأنشطة ويشكّل اللجان ويشرف على «ينابيع» و«منافع» ويؤسس المنشآت الاقتصادية.\n3 + 3\nمجلس الرقابة\nDenetim Kurulu\n3 أعضاء أساسيين و3 احتياط. يتولى الرقابة المالية والإدارية الدورية والتأكد من مطابقة الأعمال للقوانين والنظام الأساسي.\n7.2  شروط العضوية والمشاركة الرقمية\nأهلية العضوية: يحق لكل شخص طبيعي أو اعتباري يتمتع بالأهلية القانونية ويتبنى أهداف الجمعية الحصول على العضوية\nشرط الأجانب: الحصول على إقامة قانونية رسمية في البلاد\nالاجتماعات الرقمية: يجيز النظام الأساسي عقد اجتماعات الجمعية العمومية ومجلس الإدارة والأنشطة إلكترونياً وفق التشريعات المرعية، ضماناً للمرونة وسرعة الإنجاز\n7.3  منهجية التطبيق الميداني (دورة العمل التنفيذية)\n1\nالدراسة والتقييم\nالبحث الميداني وتحليل الاحتياجات المجتمعية\n2\nالتخطيط والشراكة\nتصميم المبادرات وعقد البروتوكولات مع الجهات المعنية\n3\nالتنفيذ الميداني\nإطلاق المشاريع عبر «ينابيع» و«منافع» واللجان\n4\nقياس الأثر\nالتقييم المالي والفني ورفع التقارير للرقابة","url":"governance.html#s7","page":"governance.html","section":7,"group":""},{"id":"s8","type":"section","num":"8","title":"الأحكام المالية وخطة الاستدامة والتمويل","subtitle":"مصادر الدخل وقواعد الاقتراض","text":"8.1  مصادر الدخل المعتمدة\n1\nرسوم الانتساب والاشتراكات السنوية للأعضاء\n2\nالتبرعات والهبات الطوعية من الأفراد والمؤسسات\n3\nعوائد المطبوعات والمعارض والندوات والرحلات والأنشطة\n4\nريع أصول الجمعية وممتلكاتها\n5\nالتبرعات المجمّعة وفق تشريعات جمع التبرعات\n6\nأرباح المنشآت الاقتصادية والتجارية التابعة\n7\nالمنح وبرامج الصناديق المحلية والدولية والتمويل المشترك\n8.2  قواعد الاقتراض والاستدامة\nقواعد الاقتراض\nيجوز لمجلس الإدارة أن يقرر الاقتراض عند الحاجة لتأمين الموارد اللازمة لتنفيذ الأنشطة، سواء نقداً أو عبر الشراء الآجل للبضائع والخدمات.\nإستراتيجية الاستدامة\nتضمن الجمعية ديمومة أعمالها بالتوسع في الاستثمار الاجتماعي عبر المنشآت الاقتصادية ومشاريع التمكين المهني والتوظيف، بما يحوّل المستفيدين إلى طاقات إنتاجية تدعم الاقتصاد الوطني.","url":"governance.html#s8","page":"governance.html","section":8,"group":""},{"id":"s9","type":"section","num":"9","title":"حقوق وواجبات العضو الجديد","subtitle":"ما لك وما عليك","text":"حقوق العضو\nواجبات العضو\nالمشاركة في اجتماعات الجمعية العمومية والتصويت على القرارات.\nالترشح لعضوية اللجان والمهام في مختلف الأقسام التنفيذية.\nتقديم المقترحات والمبادرات لتطوير «ينابيع» و«منافع».\nالاستفادة من البرامج التدريبية والفعاليات التي تنظمها الجمعية.\nالالتزام بأهداف الجمعية ونظامها الأساسي ومبادئها الأخلاقية.\nالمساهمة الفاعلة في تحقيق أهداف الجمعية ونشر رسالتها.\nسداد الاشتراكات السنوية المقررة وفق الأنظمة المعتمدة.\nالحفاظ على سمعة الجمعية وممتلكاتها ومكتسباتها.","url":"join.html#s9","page":"join.html","section":9,"group":""},{"id":"s10","type":"section","num":"10","title":"قياس الأثر التنموي المتوقع","subtitle":"النتائج التي نسعى إليها","text":"الأثر الاقتصادي والتوظيف\nخلق فرص عمل جديدة وتدريب الكوادر البشرية دعماً لخطط الدولة التنموية وللحد من البطالة.\nأثر التكامل المؤسسي\nتفعيل الشراكة بين الجمعيات التركية وجمعيات الجاليات بما يعظّم الاستفادة من الإمكانات ويمنع تكرار الجهود.\nالأثر المجتمعي والقيمي\nبناء أجيال متمسكة بالقيم، ونموذج عمل فاعل ومستدام يخدم كل أفراد المجتمع بأسلوب تكاملي.","url":"initiatives.html#s10","page":"initiatives.html","section":10,"group":""},{"id":"s11","type":"section","num":"11","title":"الهيئة التأسيسية للجمعية","subtitle":"الأعضاء المؤسسون الموقّعون على النظام الأساسي","text":"م\nالاسم واللقب\nرقم الهوية / الإقامة\nالجنسية\nالمهنة / المسمى\nعنوان الإقامة\n1\n[اسم المؤسس الأول]\n[رقم الهوية]\n[الجنسية]\n[المهنة]\n[العنوان التفصيلي]\n2\n[اسم المؤسس الثاني]\n[رقم الهوية]\n[الجنسية]\n[المهنة]\n[العنوان التفصيلي]\n3\n[اسم المؤسس الثالث]\n[رقم الهوية]\n[الجنسية]\n[المهنة]\n[العنوان التفصيلي]\n4\n[اسم المؤسس الرابع]\n[رقم الهوية]\n[الجنسية]\n[المهنة]\n[العنوان التفصيلي]\n5\n[اسم المؤسس الخامس]\n[رقم الهوية]\n[الجنسية]\n[المهنة]\n[العنوان التفصيلي]\n6\n[اسم المؤسس السادس]\n[رقم الهوية]\n[الجنسية]\n[المهنة]\n[العنوان التفصيلي]\n7\n[اسم المؤسس السابع]\n[رقم الهوية]\n[الجنسية]\n[المهنة]\n[العنوان التفصيلي]\n* تُعبّأ البيانات بين الأقواس بمعلومات الأعضاء المؤسسين الفعلية.","url":"join.html#s11","page":"join.html","section":11,"group":""},{"id":"s12","type":"section","num":"12","title":"لماذا أنضم إلى جمعية «تكامل»؟","subtitle":"وما الذي يميزها عن غيرها","text":"انضمامك إلى جمعية «تكامل لبناء القيم والتنمية» ليس مجرد التحاق بمؤسسة أهلية تقليدية، بل هو انحياز لنموذج تنموي فريد صاغه بعناية نخبة من رواد العمل التطوعي والإنساني، ليكون علامة فارقة ونقطة تحوّل في مسار العمل المجتمعي.\nوتتجسد قوة الجمعية في عشر ركائز إستراتيجية تجعل منها بيئة استثنائية للعطاء والأثر المستدام:\n1\nالقيادة والحوكمة\nنخبة من الكفاءات الميدانية والدولية\nتعتمد الجمعية معايير اختيار صارمة ودقيقة للأعضاء المؤسسين وأعضاء مجلس الإدارة وهيئة الرقابة ومسؤولي الأنشطة، ضماناً لقيادة مؤسسية احترافية. ويتميز قادتها بما يلي:\nكفاءة عالية وخبرة تراكمية عميقة في إدارة المشاريع والتنمية.\nوقت كافٍ للعطاء، وشبكة علاقات إستراتيجية ممتدة محلياً ودولياً.\nحسن الخلق وقدرات قيادية متميزة.\nإتقان اللغة التركية والدراية بالبيئة التشريعية والثقافية في تركيا.\n2\nالتنوع والتكامل الدولي\nمجلس إدارة يعكس روح الأمة\nتجسيداً لاسم «تكامل»، يتشكّل مجلس الإدارة من 7 أعضاء من جنسيات متعددة، مما يمنح الجمعية عمقاً ثقافياً ورؤية شاملة تتجاوز الحدود:\nتركيا\nسوريا\nفلسطين\nالعراق\nمصر\n3\nالدور التنسيقي والشبكي\nمنصة لتعظيم الموارد والخبرات\nتؤدي الجمعية دور هيئة تنسيقية شاملة، وجسر تواصل بين جمعيات الجاليات والجمعيات التركية، بهدف:\nتعظيم الاستفادة من الموارد المتاحة وتبادل الخبرات الميدانية.\nمنع تكرار الجهود وازدواجية المشاريع.\nإيجاد بيئة تنافسية إيجابية تُثمر تطويراً مستمراً للأداء والخدمات المقدمة للمجتمع.\n4\nالشمولية ونطاق الأثر\nمن إسطنبول إلى العالم\nلا تقتصر أنشطة الجمعية على ولاية بعينها أو جالية محددة، بل تمتد خدماتها لتشمل جميع المقيمين على الأرض التركية من مواطنين ومقيمين وجاليات بمختلف أطيافهم، وتتوسع وفق خطة إستراتيجية مرحلية لتصل إلى دول عديدة حول العالم.\n5\nالأمان المجتمعي والاقتصادي\nمشاريع تلامس الاحتياج الفعلي\nتتجاوز «تكامل» أدوار الإغاثة المؤقتة لتقدّم حلولاً جذرية يحتاجها كل فرد ليعيش في أمان واستقرار، عبر مسارين تنمويين:\nمشروع «ينابيع»\nالأمان المجتمعي والحماية الفكرية والقيمية للأبناء والأسر.\nمشروع «منافع»\nالأمان الاقتصادي والوظيفي عبر التدريب والتأهيل المهني وتوفير فرص العمل والتشغيل.\n6\nالتحول الرقمي والذكاء الاصطناعي\nإدارة ذكية وقياس دقيق للأثر\nتعتمد الجمعية على أدوات العصر عبر برنامج تقني متكامل لإدارة أنشطتها، وبالاستعانة بخريجي البرمجة والتكنولوجيا والذكاء الاصطناعي، بما يوفر:\nإدارة ذكية للعمليات الميدانية والإدارية.\nقياساً دقيقاً ومستمراً للأداء والأثر التنموي لمشاريع الجمعية على المستفيدين.\n7\nالاستثمار في أجيال المستقبل\nربط الأكاديميا بالقيادة الشابة\nتولي الجمعية اهتماماً خاصاً بإشراك أعضاء هيئة التدريس والأكاديميين في مجلس الإدارة وإدارة الأنشطة، ليكونوا:\nجسراً متيناً لاستقطاب الكفاءات والمواهب الشابة من الطلبة وتأطيرها.\nحاضنةً لإعداد هؤلاء الشباب وتأهيلهم ليكونوا أعضاء فاعلين وقادة للجمعية والمجتمع مستقبلاً.\n8\nالتجديد المؤسسي وتداول القيادة\nالاستدامة وتوريث الخبرات\nتكرّس الجمعية حوكمة رشيدة تمنع الجمود وتضمن ضخ دماء جديدة، عبر سياسة واضحة لمدد القيادة:\nمجلس الإدارة\nلا يُجدَّد لأكثر من دورة واحدة، ومدة الدورة 4 سنوات.\nمسؤولو الأنشطة واللجان\nدورة واحدة فقط، مدتها 3 سنوات.\nويبقى أعضاء مجلس الإدارة ومسؤولو الأنشطة السابقون مستشارين تستفيد الجمعية من خبراتهم في توجيه الأعضاء الجدد؛ وهو مبدأ أساسي لتوريث العمل المؤسسي، واختيار أفضل الكفاءات، والابتكار والتطوير المستمر.\n9\nالتفرغ الإداري والتنفيذي\nتركيز أعلى وأثر أسرع\nضماناً للفاعلية وسرعة تحقيق الأهداف الميدانية، اعتمدت الجمعية نموذج التفرغ الكامل لـ 5 أعضاء من فريق العمل المؤسس، لتكون هناك أمانة تنفيذية متفرغة تدير الأنشطة وتتابع أثرها في المجتمع بكفاءة عالية.\n10\nالاستدامة والاستقلالية المالية\nنموذج التمويل الذاتي الذكي\nوضعت الهيئة التأسيسية خطة مالية محكمة تضمن قوة المؤسسة واستمراريتها بعيداً عن تقلبات التبرعات:\nالتغطية التأسيسية\nتعتمد الجمعية في عاميها الأولين على القدرة المالية الذاتية لأعضائها المؤسسين في الإنفاق على الأنشطة والبرامج.\nالاستثمار الاجتماعي التنموي\nتأسيس مشاريع اقتصادية وتطبيق رقمي ذكي (تطبيق «منافع») ليكون مورداً مالياً مستداماً يموّل أنشطة الجمعية وبرامجها بشكل دائم.\nانضمامك إلى «تكامل» يعني مشاركتك في تجربة تنموية راسخة: نموذج محكم، وقيادة خبيرة، واستدامة مضمونة.. يداً بيد لنبني الإنسان ونحقق التنمية المستدامة!","url":"join.html#s12","page":"join.html","section":12,"group":""},{"id":"s13","type":"section","num":"13","title":"دليل الإجابات الإدارية والإستراتيجية","subtitle":"أهم الأسئلة التي يحتاجها المؤسسون ومجلس الإدارة","text":"13.1  أسئلة الأعضاء المؤسسين (Founders)\nالأسس والرؤية والحوكمة والاستدامة والمخاطر\nس1\nلماذا تتواجد هذه المؤسسة الآن؟ وما المشكلة الأساسية التي نسعى لحلها، والقيمة الفريدة التي نقدمها؟\nالرد الإداري\nتوجد المؤسسة لمعالجة فجوة تنموية ومجتمعية حقيقية، تتمثل في تشتت الجهود وغياب التكامل بين منظمات المجتمع المدني التركية وجمعيات الجاليات، إلى جانب الحاجة الماسة إلى نموذج يجمع بين التنمية القيمية والتأهيل الاقتصادي المستدام.\nوتكمن قيمتنا المضافة في تحقيق «الأثر المزدوج» (Dual Impact) عبر مبادرتي «ينابيع» للبناء التربوي والقيمي و«منافع» للتمكين الاقتصادي والتوظيف، مع أداء دور المنصة التنسيقية الشاملة التي توفر الموارد وتمنع تكرار المبادرات.\nس2\nما رؤيتنا على المدى البعيد (5–10 سنوات)؟ وكيف نعرّف «النجاح»؟\nالرد الإداري\nالرؤية الإستراتيجية (2035): الوصول إلى الريادة العالمية في بناء القيم وتمكين المجتمعات إنسانياً وتنموياً.\nمفهوم النجاح: يُقاس عبر مؤشرات أداء رئيسية (KPIs) شاملة:\nالأثر الاجتماعي والقيمي\nإعداد أجيال متماسكة قيمياً وتربوياً.\nالأثر الاقتصادي\nتحويل المستفيدين من متلقّين للمساعدات إلى طاقات إنتاجية مستقلة.\nالتوسع الجغرافي\nتنفيذ الخطة المرحلية المعتمدة من إسطنبول وصولاً إلى الولايات التركية والدول الإسلامية والعالم.\nالاستدامة الذاتية\nتمويل ما لا يقل عن 50% من الميزانية التشغيلية عبر المنشآت الاقتصادية والاستثمار الاجتماعي.\nس3\nما القيم الجوهرية (Core Values) والأخلاقيات التي ستحكم ثقافة العمل؟\nالرد الإداري\nتستند ثقافة المؤسسة إلى خمسة مرتكزات أخلاقية ومؤسسية:\nالتكامل والربط (Synergy): التعاون ومنع ازدواجية الجهود.\nالتمكين والديمومة (Empowerment): التركيز على بناء الإنسان بدلاً من الرعاية المؤقتة.\nالشفافية والحوكمة (Transparency): الإفصاح المالي والإداري التام.\nالابتكار الاجتماعي (Innovation): تقديم حلول تنموية مرنة وحديثة.\nالمسؤولية والوسطية (Accountability): الالتزام بأعلى معايير الأمانة المهنية والمجتمعية.\nس4\nما الكيان القانوني والأطر التشريعية الأنسب لنشاطنا؟\nالرد الإداري\nالكيان هو جمعية أهلية تنموية مستقلة غير ربحية، مسجلة وفق أحكام قانون الجمعيات التركي في مدينة إسطنبول، ويتضمن نظامها الأساسي صلاحية تأسيس منشآت اقتصادية وتجارية استثمارية، وفتح فروع ومكاتب تمثيلية داخل تركيا وخارجها، بما يؤمّن الغطاء القانوني لجميع الأنشطة الميدانية والاستثمارية.\nس5\nكيف تُوزَّع الصلاحيات والمسؤوليات بين الهياكل المختلفة عند التأسيس؟\nالرد الإداري\nتُوزَّع الصلاحيات بناءً على ميثاق الحوكمة والنظام الأساسي:\nالجمعية العمومية (Genel Kurul): السلطة العليا للتصويت واعتماد التعديلات وإقرار السياسات العامة.\nمجلس الإدارة (Yönetim Kurulu): السلطة التنفيذية المسؤولة عن إدارة الأنشطة وتأسيس المنشآت الاقتصادية والإشراف على الأقسام التنفيذية.\nمجلس الرقابة (Denetim Kurulu): هيئة مستقلة للفحص والرقابة المالية والإدارية.\nالأمانة العامة / الإدارة التنفيذية: إدارة العمليات الميدانية والأنشطة اليومية وفق مصفوفة تفويض الصلاحيات (Delegation of Authority).\nس6\nما اللوائح التنظيمية وميثاق الحوكمة الذي يحمي حقوق المؤسسين وينظّم حالات الانضمام والخروج؟\nالرد الإداري\nيُعتمد النظام الأساسي وميثاق الحوكمة، اللذان يحددان:\nشروط وإجراءات طلب العضوية أو إنهائها أو تعليقها.\nعدم استرداد الاشتراكات أو التبرعات السابقة، حمايةً للأصول المالية للمؤسسة.\nحفظ الحقوق المعنوية والتاريخية للهيئة التأسيسية عبر سجلات وثائق التأسيس الرسمية.\nس7\nكيف نحقق الاستدامة المالية ونتجنب الاعتماد على التبرعات المؤقتة؟\nالرد الإداري\nتتحقق الاستدامة من خلال نموذج التمويل المتعدد (Hybrid Funding Model):\nالاشتراكات السنوية ورسوم الانتساب.\nأرباح وعوائد المنشآت الاقتصادية والتجارية التابعة للجمعية (الاستثمار الاجتماعي).\nالمنح والشراكات مع الصناديق والمؤسسات المحلية والدولية.\nعوائد الأنشطة والمطبوعات والمعارض، والتبرعات المجمّعة وفق التشريعات.\nس8\nما حجم رأس المال التشغيلي المطلوب (Burn Rate)؟ ومتى نصل إلى نقطة التعادل؟\nالرد الإداري\nتُحدَّد الميزانية التشغيلية التقديرية (OpEx) لكل مرحلة من مراحل التوسع، وتُحسب نقطة التعادل (Break-even Point) بربط المصاريف التشغيلية الثابتة بإيرادات المنشآت الاقتصادية وشراكات المنح، بحيث تغطي الإيرادات الذاتية المصاريف الإدارية الثابتة خلال أول 24–36 شهراً من التشغيل.\nس9\nما المخاطر التشغيلية والمالية والأمنية الرئيسية؟ وكيف نُعدّ خطط التخفيف منها؟\nالرد الإداري\nتُدار المخاطر عبر سجل المخاطر (Risk Register):\nالمخاطر القانونية والامتثال: الالتزام التام بتشريعات الجمعيات وقوانين العمل والإقامة.\nالمخاطر المالية: تطبيق سياسة احتياطي نقدي عالي السيولة يغطي التشغيل لمدة 6 أشهر على الأقل.\nمخاطر السمعة: اعتماد ميثاق إعلامي وأخلاقي صارم يحافظ على مكانة الجمعية.\n13.2  أسئلة مجلس الإدارة (Board of Directors)\nالمتابعة والأداء والرقابة المالية والامتثال والتطوير\nس1\nهل تسير الإدارة التنفيذية وفق الخطط الإستراتيجية المعتمدة؟\nالرد الإداري\nيُتحقَّق من ذلك عبر تقارير متابعة ربع سنوية (Quarterly Performance Reviews) ترفعها الأمانة العامة إلى المجلس، تقارن المخرجات الميدانية بالمستهدفات الإستراتيجية المسجلة في الخطة التشغيلية لمبادرتي «ينابيع» و«منافع».\nس2\nما مؤشرات الأداء الرئيسية (KPIs) التي يُقاس بها نجاح الإدارة التنفيذية؟\nالرد الإداري\nتتوزع المؤشرات على أربعة محاور وفق بطاقة الأداء المتوازن (Balanced Scorecard):\nالمحور المالي\nمعدل نمو الإيرادات الذاتية، ونسبة المصاريف الإدارية إلى المصاريف البرامجية.\nمحور المستفيدين\nعدد الشباب والأسر المستفيدين من التأهيل والتوظيف والورش القيمية، ومستوى رضاهم.\nمحور العمليات الداخلية\nعدد الشراكات الموقعة مع الجمعيات التركية وجمعيات الجاليات، ونسبة إنجاز المشاريع في مواعيدها.\nمحور النمو والتعلم\nنسبة الاحتفاظ بالكفاءات، وتطوير المناهج والبرامج.\nس3\nهل لدينا خطط إحلال وتعاقب وظيفي (Succession Planning) للإدارة العليا؟\nالرد الإداري\nنعم، يعتمد المجلس سياسة للتتابع القيادي تقوم على تدريب الصف الثاني في الأقسام التنفيذية الخمسة، وتوثيق جميع الأدلة الإجرائية والسياسات التشغيلية، بما يضمن استمرارية العمل وعدم ارتباطه بأشخاص بعينهم.\nس4\nهل القوائم المالية دقيقة، وتخضع لمراجعة محاسبية مستقلة وصارمة؟\nالرد الإداري\nنعم، تخضع جميع التعاملات المالية للتدقيق على مستويين:\nالرقابة الداخلية: عبر مجلس الرقابة (Denetim Kurulu) بموجب أحكام النظام الأساسي.\nالرقابة الخارجية: عبر مكاتب محاسبة قانونية معتمدة تتولى إعداد القوائم المالية والتدقيق القانوني وفق متطلبات الجهات الرسمية.\nس5\nهل تُدار التدفقات النقدية والميزانيات المعتمدة بكفاءة ودون هدر؟\nالرد الإداري\nتُدار التدفقات بموجب ميزانية تقديرية سنوية (Annual Budget) يعتمدها مجلس الإدارة، ولا يتم أي صرف إلا وفق مصفوفة الاعتماد المالي، كما يُلزم النظام المالي بعرض تحليل فروقات الميزانية (Variance Analysis) دورياً لضبط أي هدر.\nس6\nهل المؤسسة ملتزمة تماماً بالأنظمة واللوائح القانونية والضريبية بما يجنّب المجلس أي مسؤولية؟\nالرد الإداري\nتلتزم المؤسسة بأعلى مستويات الامتثال (Compliance):\nتسجيل جميع العقود والأنشطة وفق قانون الجمعيات وقانون العمل التركي.\nالتحقق من شروط الإقامة والاشتراطات القانونية لجميع الأعضاء والعاملين.\nإدارة المنشآت الاقتصادية والتجارية بحسابات ضريبية ومحاسبية مستقلة تحمي أعضاء مجلس الإدارة من أي مسؤولية شخصية.\nس7\nما المخاطر المستجدة (السوقية، القانونية، التقنية، السمعة)؟ وكيف نُعدّ خطط الطوارئ؟\nالرد الإداري\nيراجع المجلس مصفوفة المخاطر دورياً، وعند نشوء أي خطر جديد (كتغيّر القيود القانونية أو تقلبات العملة) تُفعَّل خطط البدائل:\nالتحول الرقمي لعقد الاجتماعات والندوات عن بُعد عند الحاجة.\nتنويع سلة العملات والموارد المالية للحد من مخاطر التضخم.\nالاعتماد على بروتوكولات التعاون المشترك لخفض تكاليف التشغيل المباشر.\nس8\nكيف نضمن تطوير الخدمات وتنمية الشراكات الإستراتيجية بما يحقق الاستدامة؟\nالرد الإداري\nعبر تفعيل دور قسم الدراسات والتخطيط والاستثمار الاجتماعي وقسم التنسيق والشراكات المؤسسية، اللذين يعملان على:\nإجراء دراسات ميدانية مستمرة لاحتياجات سوق العمل والمجتمع.\nتطوير الحقائب القيمية والتنموية وتسويقها.\nعقد بروتوكولات تعاون مستمرة مع الجمعيات التركية والمؤسسات الرسمية والصناديق التنموية الدولية.","url":"faq.html#s13","page":"faq.html","section":13,"group":""},{"id":"s2-1","type":"subsection","num":"2.1","title":"2.1  الأهداف الإستراتيجية","subtitle":"","text":"1\nتعزيز القيم الإيجابية\nترسيخ القيم الأخلاقية والإنسانية والوسطية في المجتمع، وبناء أجيال ذات مرجعية قيمية راسخة.\n2\nالتمكين والتأهيل\nإكساب الشباب والأسر والنساء المهارات الحياتية والاقتصادية الحديثة والتأهيل المهني.\n3\nالتكامل والتنسيق المؤسسي\nالربط بين الجمعيات التركية وجمعيات الجاليات لتفادي تكرار الجهود وتبادل الخبرات وتعظيم الاستفادة من الموارد.\n4\nمساندة التنمية والجهود الرسمية\nدعم جهود الدولة في توفير فرص العمل والتأهيل المهني والحد من التحديات الاقتصادية والبطالة.\n5\nالاستدامة والحلول الشاملة\nتقديم حلول تنموية واجتماعية واقتصادية قائمة على الشراكات الإستراتيجية والاستثمار الاجتماعي.","url":"about.html#s2-1","page":"about.html","section":2,"group":""},{"id":"s3-1","type":"subsection","num":"3.1","title":"3.1  مبادرة «ينابيع» – البناء الفكري والقيمي والتربية التفاعلية","subtitle":"","text":"مجال التركيز: التربية القيمية، والبناء الفكري، والتواصل الثقافي والمجتمعي والتكيف.\nتقديم المناهج والورش القيمية والأخلاقية للأطفال والشباب والناشئة.\nبرامج الإرشاد الأسري والتربوي والتطوير الشخصي لبناء أسر متماسكة.\nتعزيز التكيف الثقافي والتعايش المجتمعي عبر لقاءات حوارية وفعاليات ثقافية.\nملتقيات شبابية وبرامج توعوية لحماية النشء من السلوكيات الضارة.","url":"initiatives.html#s3-1","page":"initiatives.html","section":3,"group":""},{"id":"s3-2","type":"subsection","num":"3.2","title":"3.2  مبادرة «منافع» – التكافل والتضامن والتمكين الاقتصادي","subtitle":"","text":"مجال التركيز: معالجة التحديات الاقتصادية، والتمكين الاقتصادي، والتوظيف، والتكافل والتضامن.\nالتأهيل والتدريب المهني للشباب والنساء مساندةً لخطط الدولة في توفير فرص العمل.\nمنصات وشبكات تربط الكفاءات والعمالة الماهرة بسوق العمل ومؤسسات الإنتاج.\nدعم وتمويل المشاريع الصغرى والأسر المنتجة لتحقيق الاكتفاء الذاتي.\nأنشطة التكافل الاجتماعي والمساعدات غير المباشرة للأسر المتعففة.","url":"initiatives.html#s3-2","page":"initiatives.html","section":3,"group":""},{"id":"s3-3","type":"subsection","num":"3.3","title":"3.3  محور التنسيق والتكامل المؤسسي والأنشطة المساندة","subtitle":"","text":"تكامل الموارد\nالربط بين الجمعيات التركية وجمعيات الجاليات لإقامة أنشطة مشتركة وتكامل الخدمات.\nالدعم التقني\nتقديم الدعم التقني والتأهيل التنموي للفئات المستضعفة والمحتاجة.\nالأبحاث والدراسات\nدراسات ميدانية حول سوق العمل والواقع المجتمعي، وإصدار الحقائب والمجلات التوعوية.\nالصلاحية العامة\nممارسة الأنشطة الاجتماعية والثقافية والتعليمية والاقتصادية والرياضية، وتأسيس منشآت اقتصادية، والاستفادة من المنح، وتوقيع بروتوكولات التعاون.","url":"initiatives.html#s3-3","page":"initiatives.html","section":3,"group":""},{"id":"s4-1","type":"subsection","num":"4.1","title":"4.1  فلسفة العمل","subtitle":"","text":"التكامل والربط\nSynergy\nتنسيق فاعل بين الجمعيات الأهلية لبناء شراكات مثمرة واستثمار الموارد بكفاءة.\nالتمكين والديمومة\nEmpowerment\nالانتقال من الإغاثة المباشرة إلى التأهيل المهني والتمكين الإنتاجي المستدام.\nالأثر المزدوج\nDual Impact\nجمع متوازن بين البناء القيمي (ينابيع) والتمكين الاقتصادي والاجتماعي (منافع).\nالاستدامة الذاتية\nSelf-Sustainability\nتشغيل استثماري واجتماعي يضمن موارد ثابتة لتمويل البرامج.","url":"about.html#s4-1","page":"about.html","section":4,"group":""},{"id":"s4-2","type":"subsection","num":"4.2","title":"4.2  الأقسام التنفيذية داخل الجمعية","subtitle":"","text":"القسم\nالمهام الرئيسية\nقسم البرامج القيمية والتربوية\nإعداد البرامج التربوية والمناهج القيمية لمبادرة «ينابيع» وتطبيقها.\nقسم التنسيق والعلاقات بين الجمعيات\nبناء شبكة العلاقات المؤسسية والأنشطة المشتركة بين الجمعيات.\nقسم التأهيل المهني والتوظيف\nإدارة دورات التدريب المهني ومنصات التوظيف والمشاريع الصغرى ضمن «منافع».\nقسم التكافل والتضامن الاجتماعي\nالمسح الميداني والدعم الاجتماعي المباشر للأسر والطلاب.\nقسم الدراسات والتخطيط والاستثمار الاجتماعي\nالبحث الميداني ومتابعة جودة الأداء وإدارة المطبوعات وتشغيل المنشآت الاقتصادية.","url":"about.html#s4-2","page":"about.html","section":4,"group":""},{"id":"s7-1","type":"subsection","num":"7.1","title":"7.1  الهيكل الإداري والحوكمة المؤسسية","subtitle":"","text":"جميع الأعضاء\nالجمعية العمومية\nGenel Kurul\nالسلطة العليا في الجمعية؛ تجتمع اجتماعاً عادياً كل 3 سنوات في شهر أبريل، وتختص بتعديل النظام الأساسي وإقرار السياسات العامة والتصويت.\n5 + 5\nمجلس الإدارة\nYönetim Kurulu\n5 أعضاء أساسيين و5 احتياط. السلطة التنفيذية الممثلة للجمعية: يدير الأنشطة ويشكّل اللجان ويشرف على «ينابيع» و«منافع» ويؤسس المنشآت الاقتصادية.\n3 + 3\nمجلس الرقابة\nDenetim Kurulu\n3 أعضاء أساسيين و3 احتياط. يتولى الرقابة المالية والإدارية الدورية والتأكد من مطابقة الأعمال للقوانين والنظام الأساسي.","url":"governance.html#s7-1","page":"governance.html","section":7,"group":""},{"id":"s7-2","type":"subsection","num":"7.2","title":"7.2  شروط العضوية والمشاركة الرقمية","subtitle":"","text":"أهلية العضوية: يحق لكل شخص طبيعي أو اعتباري يتمتع بالأهلية القانونية ويتبنى أهداف الجمعية الحصول على العضوية\nشرط الأجانب: الحصول على إقامة قانونية رسمية في البلاد\nالاجتماعات الرقمية: يجيز النظام الأساسي عقد اجتماعات الجمعية العمومية ومجلس الإدارة والأنشطة إلكترونياً وفق التشريعات المرعية، ضماناً للمرونة وسرعة الإنجاز","url":"governance.html#s7-2","page":"governance.html","section":7,"group":""},{"id":"s7-3","type":"subsection","num":"7.3","title":"7.3  منهجية التطبيق الميداني (دورة العمل التنفيذية)","subtitle":"","text":"1\nالدراسة والتقييم\nالبحث الميداني وتحليل الاحتياجات المجتمعية\n2\nالتخطيط والشراكة\nتصميم المبادرات وعقد البروتوكولات مع الجهات المعنية\n3\nالتنفيذ الميداني\nإطلاق المشاريع عبر «ينابيع» و«منافع» واللجان\n4\nقياس الأثر\nالتقييم المالي والفني ورفع التقارير للرقابة","url":"governance.html#s7-3","page":"governance.html","section":7,"group":""},{"id":"s8-1","type":"subsection","num":"8.1","title":"8.1  مصادر الدخل المعتمدة","subtitle":"","text":"1\nرسوم الانتساب والاشتراكات السنوية للأعضاء\n2\nالتبرعات والهبات الطوعية من الأفراد والمؤسسات\n3\nعوائد المطبوعات والمعارض والندوات والرحلات والأنشطة\n4\nريع أصول الجمعية وممتلكاتها\n5\nالتبرعات المجمّعة وفق تشريعات جمع التبرعات\n6\nأرباح المنشآت الاقتصادية والتجارية التابعة\n7\nالمنح وبرامج الصناديق المحلية والدولية والتمويل المشترك","url":"governance.html#s8-1","page":"governance.html","section":8,"group":""},{"id":"s8-2","type":"subsection","num":"8.2","title":"8.2  قواعد الاقتراض والاستدامة","subtitle":"","text":"قواعد الاقتراض\nيجوز لمجلس الإدارة أن يقرر الاقتراض عند الحاجة لتأمين الموارد اللازمة لتنفيذ الأنشطة، سواء نقداً أو عبر الشراء الآجل للبضائع والخدمات.\nإستراتيجية الاستدامة\nتضمن الجمعية ديمومة أعمالها بالتوسع في الاستثمار الاجتماعي عبر المنشآت الاقتصادية ومشاريع التمكين المهني والتوظيف، بما يحوّل المستفيدين إلى طاقات إنتاجية تدعم الاقتصاد الوطني.","url":"governance.html#s8-2","page":"governance.html","section":8,"group":""},{"id":"s13-1","type":"subsection","num":"13.1","title":"13.1  أسئلة الأعضاء المؤسسين (Founders)","subtitle":"","text":"الأسس والرؤية والحوكمة والاستدامة والمخاطر\nس1\nلماذا تتواجد هذه المؤسسة الآن؟ وما المشكلة الأساسية التي نسعى لحلها، والقيمة الفريدة التي نقدمها؟\nالرد الإداري\nتوجد المؤسسة لمعالجة فجوة تنموية ومجتمعية حقيقية، تتمثل في تشتت الجهود وغياب التكامل بين منظمات المجتمع المدني التركية وجمعيات الجاليات، إلى جانب الحاجة الماسة إلى نموذج يجمع بين التنمية القيمية والتأهيل الاقتصادي المستدام.\nوتكمن قيمتنا المضافة في تحقيق «الأثر المزدوج» (Dual Impact) عبر مبادرتي «ينابيع» للبناء التربوي والقيمي و«منافع» للتمكين الاقتصادي والتوظيف، مع أداء دور المنصة التنسيقية الشاملة التي توفر الموارد وتمنع تكرار المبادرات.\nس2\nما رؤيتنا على المدى البعيد (5–10 سنوات)؟ وكيف نعرّف «النجاح»؟\nالرد الإداري\nالرؤية الإستراتيجية (2035): الوصول إلى الريادة العالمية في بناء القيم وتمكين المجتمعات إنسانياً وتنموياً.\nمفهوم النجاح: يُقاس عبر مؤشرات أداء رئيسية (KPIs) شاملة:\nالأثر الاجتماعي والقيمي\nإعداد أجيال متماسكة قيمياً وتربوياً.\nالأثر الاقتصادي\nتحويل المستفيدين من متلقّين للمساعدات إلى طاقات إنتاجية مستقلة.\nالتوسع الجغرافي\nتنفيذ الخطة المرحلية المعتمدة من إسطنبول وصولاً إلى الولايات التركية والدول الإسلامية والعالم.\nالاستدامة الذاتية\nتمويل ما لا يقل عن 50% من الميزانية التشغيلية عبر المنشآت الاقتصادية والاستثمار الاجتماعي.\nس3\nما القيم الجوهرية (Core Values) والأخلاقيات التي ستحكم ثقافة العمل؟\nالرد الإداري\nتستند ثقافة المؤسسة إلى خمسة مرتكزات أخلاقية ومؤسسية:\nالتكامل والربط (Synergy): التعاون ومنع ازدواجية الجهود.\nالتمكين والديمومة (Empowerment): التركيز على بناء الإنسان بدلاً من الرعاية المؤقتة.\nالشفافية والحوكمة (Transparency): الإفصاح المالي والإداري التام.\nالابتكار الاجتماعي (Innovation): تقديم حلول تنموية مرنة وحديثة.\nالمسؤولية والوسطية (Accountability): الالتزام بأعلى معايير الأمانة المهنية والمجتمعية.\nس4\nما الكيان القانوني والأطر التشريعية الأنسب لنشاطنا؟\nالرد الإداري\nالكيان هو جمعية أهلية تنموية مستقلة غير ربحية، مسجلة وفق أحكام قانون الجمعيات التركي في مدينة إسطنبول، ويتضمن نظامها الأساسي صلاحية تأسيس منشآت اقتصادية وتجارية استثمارية، وفتح فروع ومكاتب تمثيلية داخل تركيا وخارجها، بما يؤمّن الغطاء القانوني لجميع الأنشطة الميدانية والاستثمارية.\nس5\nكيف تُوزَّع الصلاحيات والمسؤوليات بين الهياكل المختلفة عند التأسيس؟\nالرد الإداري\nتُوزَّع الصلاحيات بناءً على ميثاق الحوكمة والنظام الأساسي:\nالجمعية العمومية (Genel Kurul): السلطة العليا للتصويت واعتماد التعديلات وإقرار السياسات العامة.\nمجلس الإدارة (Yönetim Kurulu): السلطة التنفيذية المسؤولة عن إدارة الأنشطة وتأسيس المنشآت الاقتصادية والإشراف على الأقسام التنفيذية.\nمجلس الرقابة (Denetim Kurulu): هيئة مستقلة للفحص والرقابة المالية والإدارية.\nالأمانة العامة / الإدارة التنفيذية: إدارة العمليات الميدانية والأنشطة اليومية وفق مصفوفة تفويض الصلاحيات (Delegation of Authority).\nس6\nما اللوائح التنظيمية وميثاق الحوكمة الذي يحمي حقوق المؤسسين وينظّم حالات الانضمام والخروج؟\nالرد الإداري\nيُعتمد النظام الأساسي وميثاق الحوكمة، اللذان يحددان:\nشروط وإجراءات طلب العضوية أو إنهائها أو تعليقها.\nعدم استرداد الاشتراكات أو التبرعات السابقة، حمايةً للأصول المالية للمؤسسة.\nحفظ الحقوق المعنوية والتاريخية للهيئة التأسيسية عبر سجلات وثائق التأسيس الرسمية.\nس7\nكيف نحقق الاستدامة المالية ونتجنب الاعتماد على التبرعات المؤقتة؟\nالرد الإداري\nتتحقق الاستدامة من خلال نموذج التمويل المتعدد (Hybrid Funding Model):\nالاشتراكات السنوية ورسوم الانتساب.\nأرباح وعوائد المنشآت الاقتصادية والتجارية التابعة للجمعية (الاستثمار الاجتماعي).\nالمنح والشراكات مع الصناديق والمؤسسات المحلية والدولية.\nعوائد الأنشطة والمطبوعات والمعارض، والتبرعات المجمّعة وفق التشريعات.\nس8\nما حجم رأس المال التشغيلي المطلوب (Burn Rate)؟ ومتى نصل إلى نقطة التعادل؟\nالرد الإداري\nتُحدَّد الميزانية التشغيلية التقديرية (OpEx) لكل مرحلة من مراحل التوسع، وتُحسب نقطة التعادل (Break-even Point) بربط المصاريف التشغيلية الثابتة بإيرادات المنشآت الاقتصادية وشراكات المنح، بحيث تغطي الإيرادات الذاتية المصاريف الإدارية الثابتة خلال أول 24–36 شهراً من التشغيل.\nس9\nما المخاطر التشغيلية والمالية والأمنية الرئيسية؟ وكيف نُعدّ خطط التخفيف منها؟\nالرد الإداري\nتُدار المخاطر عبر سجل المخاطر (Risk Register):\nالمخاطر القانونية والامتثال: الالتزام التام بتشريعات الجمعيات وقوانين العمل والإقامة.\nالمخاطر المالية: تطبيق سياسة احتياطي نقدي عالي السيولة يغطي التشغيل لمدة 6 أشهر على الأقل.\nمخاطر السمعة: اعتماد ميثاق إعلامي وأخلاقي صارم يحافظ على مكانة الجمعية.","url":"faq.html#s13-1","page":"faq.html","section":13,"group":""},{"id":"s13-2","type":"subsection","num":"13.2","title":"13.2  أسئلة مجلس الإدارة (Board of Directors)","subtitle":"","text":"المتابعة والأداء والرقابة المالية والامتثال والتطوير\nس1\nهل تسير الإدارة التنفيذية وفق الخطط الإستراتيجية المعتمدة؟\nالرد الإداري\nيُتحقَّق من ذلك عبر تقارير متابعة ربع سنوية (Quarterly Performance Reviews) ترفعها الأمانة العامة إلى المجلس، تقارن المخرجات الميدانية بالمستهدفات الإستراتيجية المسجلة في الخطة التشغيلية لمبادرتي «ينابيع» و«منافع».\nس2\nما مؤشرات الأداء الرئيسية (KPIs) التي يُقاس بها نجاح الإدارة التنفيذية؟\nالرد الإداري\nتتوزع المؤشرات على أربعة محاور وفق بطاقة الأداء المتوازن (Balanced Scorecard):\nالمحور المالي\nمعدل نمو الإيرادات الذاتية، ونسبة المصاريف الإدارية إلى المصاريف البرامجية.\nمحور المستفيدين\nعدد الشباب والأسر المستفيدين من التأهيل والتوظيف والورش القيمية، ومستوى رضاهم.\nمحور العمليات الداخلية\nعدد الشراكات الموقعة مع الجمعيات التركية وجمعيات الجاليات، ونسبة إنجاز المشاريع في مواعيدها.\nمحور النمو والتعلم\nنسبة الاحتفاظ بالكفاءات، وتطوير المناهج والبرامج.\nس3\nهل لدينا خطط إحلال وتعاقب وظيفي (Succession Planning) للإدارة العليا؟\nالرد الإداري\nنعم، يعتمد المجلس سياسة للتتابع القيادي تقوم على تدريب الصف الثاني في الأقسام التنفيذية الخمسة، وتوثيق جميع الأدلة الإجرائية والسياسات التشغيلية، بما يضمن استمرارية العمل وعدم ارتباطه بأشخاص بعينهم.\nس4\nهل القوائم المالية دقيقة، وتخضع لمراجعة محاسبية مستقلة وصارمة؟\nالرد الإداري\nنعم، تخضع جميع التعاملات المالية للتدقيق على مستويين:\nالرقابة الداخلية: عبر مجلس الرقابة (Denetim Kurulu) بموجب أحكام النظام الأساسي.\nالرقابة الخارجية: عبر مكاتب محاسبة قانونية معتمدة تتولى إعداد القوائم المالية والتدقيق القانوني وفق متطلبات الجهات الرسمية.\nس5\nهل تُدار التدفقات النقدية والميزانيات المعتمدة بكفاءة ودون هدر؟\nالرد الإداري\nتُدار التدفقات بموجب ميزانية تقديرية سنوية (Annual Budget) يعتمدها مجلس الإدارة، ولا يتم أي صرف إلا وفق مصفوفة الاعتماد المالي، كما يُلزم النظام المالي بعرض تحليل فروقات الميزانية (Variance Analysis) دورياً لضبط أي هدر.\nس6\nهل المؤسسة ملتزمة تماماً بالأنظمة واللوائح القانونية والضريبية بما يجنّب المجلس أي مسؤولية؟\nالرد الإداري\nتلتزم المؤسسة بأعلى مستويات الامتثال (Compliance):\nتسجيل جميع العقود والأنشطة وفق قانون الجمعيات وقانون العمل التركي.\nالتحقق من شروط الإقامة والاشتراطات القانونية لجميع الأعضاء والعاملين.\nإدارة المنشآت الاقتصادية والتجارية بحسابات ضريبية ومحاسبية مستقلة تحمي أعضاء مجلس الإدارة من أي مسؤولية شخصية.\nس7\nما المخاطر المستجدة (السوقية، القانونية، التقنية، السمعة)؟ وكيف نُعدّ خطط الطوارئ؟\nالرد الإداري\nيراجع المجلس مصفوفة المخاطر دورياً، وعند نشوء أي خطر جديد (كتغيّر القيود القانونية أو تقلبات العملة) تُفعَّل خطط البدائل:\nالتحول الرقمي لعقد الاجتماعات والندوات عن بُعد عند الحاجة.\nتنويع سلة العملات والموارد المالية للحد من مخاطر التضخم.\nالاعتماد على بروتوكولات التعاون المشترك لخفض تكاليف التشغيل المباشر.\nس8\nكيف نضمن تطوير الخدمات وتنمية الشراكات الإستراتيجية بما يحقق الاستدامة؟\nالرد الإداري\nعبر تفعيل دور قسم الدراسات والتخطيط والاستثمار الاجتماعي وقسم التنسيق والشراكات المؤسسية، اللذين يعملان على:\nإجراء دراسات ميدانية مستمرة لاحتياجات سوق العمل والمجتمع.\nتطوير الحقائب القيمية والتنموية وتسويقها.\nعقد بروتوكولات تعاون مستمرة مع الجمعيات التركية والمؤسسات الرسمية والصناديق التنموية الدولية.","url":"faq.html#s13-2","page":"faq.html","section":13,"group":""},{"id":"p1","type":"pillar","num":"1","title":"القيادة والحوكمة","subtitle":"نخبة من الكفاءات الميدانية والدولية","text":"تعتمد الجمعية معايير اختيار صارمة ودقيقة للأعضاء المؤسسين وأعضاء مجلس الإدارة وهيئة الرقابة ومسؤولي الأنشطة، ضماناً لقيادة مؤسسية احترافية. ويتميز قادتها بما يلي:\nكفاءة عالية وخبرة تراكمية عميقة في إدارة المشاريع والتنمية.\nوقت كافٍ للعطاء، وشبكة علاقات إستراتيجية ممتدة محلياً ودولياً.\nحسن الخلق وقدرات قيادية متميزة.\nإتقان اللغة التركية والدراية بالبيئة التشريعية والثقافية في تركيا.","url":"join.html#p1","page":"join.html","section":12,"group":""},{"id":"p2","type":"pillar","num":"2","title":"التنوع والتكامل الدولي","subtitle":"مجلس إدارة يعكس روح الأمة","text":"تجسيداً لاسم «تكامل»، يتشكّل مجلس الإدارة من 7 أعضاء من جنسيات متعددة، مما يمنح الجمعية عمقاً ثقافياً ورؤية شاملة تتجاوز الحدود:\nتركيا\nسوريا\nفلسطين\nالعراق\nمصر","url":"join.html#p2","page":"join.html","section":12,"group":""},{"id":"p3","type":"pillar","num":"3","title":"الدور التنسيقي والشبكي","subtitle":"منصة لتعظيم الموارد والخبرات","text":"تؤدي الجمعية دور هيئة تنسيقية شاملة، وجسر تواصل بين جمعيات الجاليات والجمعيات التركية، بهدف:\nتعظيم الاستفادة من الموارد المتاحة وتبادل الخبرات الميدانية.\nمنع تكرار الجهود وازدواجية المشاريع.\nإيجاد بيئة تنافسية إيجابية تُثمر تطويراً مستمراً للأداء والخدمات المقدمة للمجتمع.","url":"join.html#p3","page":"join.html","section":12,"group":""},{"id":"p4","type":"pillar","num":"4","title":"الشمولية ونطاق الأثر","subtitle":"من إسطنبول إلى العالم","text":"لا تقتصر أنشطة الجمعية على ولاية بعينها أو جالية محددة، بل تمتد خدماتها لتشمل جميع المقيمين على الأرض التركية من مواطنين ومقيمين وجاليات بمختلف أطيافهم، وتتوسع وفق خطة إستراتيجية مرحلية لتصل إلى دول عديدة حول العالم.","url":"join.html#p4","page":"join.html","section":12,"group":""},{"id":"p5","type":"pillar","num":"5","title":"الأمان المجتمعي والاقتصادي","subtitle":"مشاريع تلامس الاحتياج الفعلي","text":"تتجاوز «تكامل» أدوار الإغاثة المؤقتة لتقدّم حلولاً جذرية يحتاجها كل فرد ليعيش في أمان واستقرار، عبر مسارين تنمويين:\nمشروع «ينابيع»\nالأمان المجتمعي والحماية الفكرية والقيمية للأبناء والأسر.\nمشروع «منافع»\nالأمان الاقتصادي والوظيفي عبر التدريب والتأهيل المهني وتوفير فرص العمل والتشغيل.","url":"join.html#p5","page":"join.html","section":12,"group":""},{"id":"p6","type":"pillar","num":"6","title":"التحول الرقمي والذكاء الاصطناعي","subtitle":"إدارة ذكية وقياس دقيق للأثر","text":"تعتمد الجمعية على أدوات العصر عبر برنامج تقني متكامل لإدارة أنشطتها، وبالاستعانة بخريجي البرمجة والتكنولوجيا والذكاء الاصطناعي، بما يوفر:\nإدارة ذكية للعمليات الميدانية والإدارية.\nقياساً دقيقاً ومستمراً للأداء والأثر التنموي لمشاريع الجمعية على المستفيدين.","url":"join.html#p6","page":"join.html","section":12,"group":""},{"id":"p7","type":"pillar","num":"7","title":"الاستثمار في أجيال المستقبل","subtitle":"ربط الأكاديميا بالقيادة الشابة","text":"تولي الجمعية اهتماماً خاصاً بإشراك أعضاء هيئة التدريس والأكاديميين في مجلس الإدارة وإدارة الأنشطة، ليكونوا:\nجسراً متيناً لاستقطاب الكفاءات والمواهب الشابة من الطلبة وتأطيرها.\nحاضنةً لإعداد هؤلاء الشباب وتأهيلهم ليكونوا أعضاء فاعلين وقادة للجمعية والمجتمع مستقبلاً.","url":"join.html#p7","page":"join.html","section":12,"group":""},{"id":"p8","type":"pillar","num":"8","title":"التجديد المؤسسي وتداول القيادة","subtitle":"الاستدامة وتوريث الخبرات","text":"تكرّس الجمعية حوكمة رشيدة تمنع الجمود وتضمن ضخ دماء جديدة، عبر سياسة واضحة لمدد القيادة:\nمجلس الإدارة\nلا يُجدَّد لأكثر من دورة واحدة، ومدة الدورة 4 سنوات.\nمسؤولو الأنشطة واللجان\nدورة واحدة فقط، مدتها 3 سنوات.\nويبقى أعضاء مجلس الإدارة ومسؤولو الأنشطة السابقون مستشارين تستفيد الجمعية من خبراتهم في توجيه الأعضاء الجدد؛ وهو مبدأ أساسي لتوريث العمل المؤسسي، واختيار أفضل الكفاءات، والابتكار والتطوير المستمر.","url":"join.html#p8","page":"join.html","section":12,"group":""},{"id":"p9","type":"pillar","num":"9","title":"التفرغ الإداري والتنفيذي","subtitle":"تركيز أعلى وأثر أسرع","text":"ضماناً للفاعلية وسرعة تحقيق الأهداف الميدانية، اعتمدت الجمعية نموذج التفرغ الكامل لـ 5 أعضاء من فريق العمل المؤسس، لتكون هناك أمانة تنفيذية متفرغة تدير الأنشطة وتتابع أثرها في المجتمع بكفاءة عالية.","url":"join.html#p9","page":"join.html","section":12,"group":""},{"id":"p10","type":"pillar","num":"10","title":"الاستدامة والاستقلالية المالية","subtitle":"نموذج التمويل الذاتي الذكي","text":"وضعت الهيئة التأسيسية خطة مالية محكمة تضمن قوة المؤسسة واستمراريتها بعيداً عن تقلبات التبرعات:\nالتغطية التأسيسية\nتعتمد الجمعية في عاميها الأولين على القدرة المالية الذاتية لأعضائها المؤسسين في الإنفاق على الأنشطة والبرامج.\nالاستثمار الاجتماعي التنموي\nتأسيس مشاريع اقتصادية وتطبيق رقمي ذكي (تطبيق «منافع») ليكون مورداً مالياً مستداماً يموّل أنشطة الجمعية وبرامجها بشكل دائم.","url":"join.html#p10","page":"join.html","section":12,"group":""},{"id":"st1","type":"stage","num":"1","title":"إسطنبول","subtitle":"المرحلة 1","text":"التأسيس وبناء النموذج التشغيلي المعياري واختبار المبادرات.","url":"expansion.html#st1","page":"expansion.html","section":5,"group":""},{"id":"st2","type":"stage","num":"2","title":"أنقرة","subtitle":"المرحلة 2","text":"تعزيز الحضور في العاصمة وبناء الشراكات المركزية مع المؤسسات الرسمية.","url":"expansion.html#st2","page":"expansion.html","section":5,"group":""},{"id":"st3","type":"stage","num":"3","title":"أكبر 10 ولايات تركية","subtitle":"المرحلة 3","text":"نشر النموذج وتغطية الكثافات السكانية الكبرى عبر فروع ومكاتب تمثيلية.","url":"expansion.html#st3","page":"expansion.html","section":5,"group":""},{"id":"st4","type":"stage","num":"4","title":"كافة الولايات التركية","subtitle":"المرحلة 4","text":"تحقيق التغطية الوطنية الشاملة.","url":"expansion.html#st4","page":"expansion.html","section":5,"group":""},{"id":"st5","type":"stage","num":"5","title":"أهم 10 دول إسلامية","subtitle":"المرحلة 5","text":"نقل التجربة وتأسيس شراكات إقليمية لتصدير الحقائب القيمية والتنموية.","url":"expansion.html#st5","page":"expansion.html","section":5,"group":""},{"id":"st6","type":"stage","num":"6","title":"باقي الدول الإسلامية","subtitle":"المرحلة 6","text":"تعميق الأثر وتفعيل التكافل والتكامل التنموي الإسلامي.","url":"expansion.html#st6","page":"expansion.html","section":5,"group":""},{"id":"st7","type":"stage","num":"7","title":"الدول ذات الأهمية العالمية","subtitle":"المرحلة 7","text":"التواصل مع الجاليات والمجتمعات العالمية وبناء نموذج عمل إنساني وقيمي عالمي.","url":"expansion.html#st7","page":"expansion.html","section":5,"group":""},{"id":"f1","type":"faq","num":"س1","title":"لماذا تتواجد هذه المؤسسة الآن؟ وما المشكلة الأساسية التي نسعى لحلها، والقيمة الفريدة التي نقدمها؟","subtitle":"","text":"توجد المؤسسة لمعالجة فجوة تنموية ومجتمعية حقيقية، تتمثل في تشتت الجهود وغياب التكامل بين منظمات المجتمع المدني التركية وجمعيات الجاليات، إلى جانب الحاجة الماسة إلى نموذج يجمع بين التنمية القيمية والتأهيل الاقتصادي المستدام.\nوتكمن قيمتنا المضافة في تحقيق «الأثر المزدوج» (Dual Impact) عبر مبادرتي «ينابيع» للبناء التربوي والقيمي و«منافع» للتمكين الاقتصادي والتوظيف، مع أداء دور المنصة التنسيقية الشاملة التي توفر الموارد وتمنع تكرار المبادرات.","url":"faq.html#f1","page":"faq.html","section":13,"group":"founders"},{"id":"f2","type":"faq","num":"س2","title":"ما رؤيتنا على المدى البعيد (5–10 سنوات)؟ وكيف نعرّف «النجاح»؟","subtitle":"","text":"الرؤية الإستراتيجية (2035): الوصول إلى الريادة العالمية في بناء القيم وتمكين المجتمعات إنسانياً وتنموياً.\nمفهوم النجاح: يُقاس عبر مؤشرات أداء رئيسية (KPIs) شاملة:\nالأثر الاجتماعي والقيمي\nإعداد أجيال متماسكة قيمياً وتربوياً.\nالأثر الاقتصادي\nتحويل المستفيدين من متلقّين للمساعدات إلى طاقات إنتاجية مستقلة.\nالتوسع الجغرافي\nتنفيذ الخطة المرحلية المعتمدة من إسطنبول وصولاً إلى الولايات التركية والدول الإسلامية والعالم.\nالاستدامة الذاتية\nتمويل ما لا يقل عن 50% من الميزانية التشغيلية عبر المنشآت الاقتصادية والاستثمار الاجتماعي.","url":"faq.html#f2","page":"faq.html","section":13,"group":"founders"},{"id":"f3","type":"faq","num":"س3","title":"ما القيم الجوهرية (Core Values) والأخلاقيات التي ستحكم ثقافة العمل؟","subtitle":"","text":"تستند ثقافة المؤسسة إلى خمسة مرتكزات أخلاقية ومؤسسية:\nالتكامل والربط (Synergy): التعاون ومنع ازدواجية الجهود.\nالتمكين والديمومة (Empowerment): التركيز على بناء الإنسان بدلاً من الرعاية المؤقتة.\nالشفافية والحوكمة (Transparency): الإفصاح المالي والإداري التام.\nالابتكار الاجتماعي (Innovation): تقديم حلول تنموية مرنة وحديثة.\nالمسؤولية والوسطية (Accountability): الالتزام بأعلى معايير الأمانة المهنية والمجتمعية.","url":"faq.html#f3","page":"faq.html","section":13,"group":"founders"},{"id":"f4","type":"faq","num":"س4","title":"ما الكيان القانوني والأطر التشريعية الأنسب لنشاطنا؟","subtitle":"","text":"الكيان هو جمعية أهلية تنموية مستقلة غير ربحية، مسجلة وفق أحكام قانون الجمعيات التركي في مدينة إسطنبول، ويتضمن نظامها الأساسي صلاحية تأسيس منشآت اقتصادية وتجارية استثمارية، وفتح فروع ومكاتب تمثيلية داخل تركيا وخارجها، بما يؤمّن الغطاء القانوني لجميع الأنشطة الميدانية والاستثمارية.","url":"faq.html#f4","page":"faq.html","section":13,"group":"founders"},{"id":"f5","type":"faq","num":"س5","title":"كيف تُوزَّع الصلاحيات والمسؤوليات بين الهياكل المختلفة عند التأسيس؟","subtitle":"","text":"تُوزَّع الصلاحيات بناءً على ميثاق الحوكمة والنظام الأساسي:\nالجمعية العمومية (Genel Kurul): السلطة العليا للتصويت واعتماد التعديلات وإقرار السياسات العامة.\nمجلس الإدارة (Yönetim Kurulu): السلطة التنفيذية المسؤولة عن إدارة الأنشطة وتأسيس المنشآت الاقتصادية والإشراف على الأقسام التنفيذية.\nمجلس الرقابة (Denetim Kurulu): هيئة مستقلة للفحص والرقابة المالية والإدارية.\nالأمانة العامة / الإدارة التنفيذية: إدارة العمليات الميدانية والأنشطة اليومية وفق مصفوفة تفويض الصلاحيات (Delegation of Authority).","url":"faq.html#f5","page":"faq.html","section":13,"group":"founders"},{"id":"f6","type":"faq","num":"س6","title":"ما اللوائح التنظيمية وميثاق الحوكمة الذي يحمي حقوق المؤسسين وينظّم حالات الانضمام والخروج؟","subtitle":"","text":"يُعتمد النظام الأساسي وميثاق الحوكمة، اللذان يحددان:\nشروط وإجراءات طلب العضوية أو إنهائها أو تعليقها.\nعدم استرداد الاشتراكات أو التبرعات السابقة، حمايةً للأصول المالية للمؤسسة.\nحفظ الحقوق المعنوية والتاريخية للهيئة التأسيسية عبر سجلات وثائق التأسيس الرسمية.","url":"faq.html#f6","page":"faq.html","section":13,"group":"founders"},{"id":"f7","type":"faq","num":"س7","title":"كيف نحقق الاستدامة المالية ونتجنب الاعتماد على التبرعات المؤقتة؟","subtitle":"","text":"تتحقق الاستدامة من خلال نموذج التمويل المتعدد (Hybrid Funding Model):\nالاشتراكات السنوية ورسوم الانتساب.\nأرباح وعوائد المنشآت الاقتصادية والتجارية التابعة للجمعية (الاستثمار الاجتماعي).\nالمنح والشراكات مع الصناديق والمؤسسات المحلية والدولية.\nعوائد الأنشطة والمطبوعات والمعارض، والتبرعات المجمّعة وفق التشريعات.","url":"faq.html#f7","page":"faq.html","section":13,"group":"founders"},{"id":"f8","type":"faq","num":"س8","title":"ما حجم رأس المال التشغيلي المطلوب (Burn Rate)؟ ومتى نصل إلى نقطة التعادل؟","subtitle":"","text":"تُحدَّد الميزانية التشغيلية التقديرية (OpEx) لكل مرحلة من مراحل التوسع، وتُحسب نقطة التعادل (Break-even Point) بربط المصاريف التشغيلية الثابتة بإيرادات المنشآت الاقتصادية وشراكات المنح، بحيث تغطي الإيرادات الذاتية المصاريف الإدارية الثابتة خلال أول 24–36 شهراً من التشغيل.","url":"faq.html#f8","page":"faq.html","section":13,"group":"founders"},{"id":"f9","type":"faq","num":"س9","title":"ما المخاطر التشغيلية والمالية والأمنية الرئيسية؟ وكيف نُعدّ خطط التخفيف منها؟","subtitle":"","text":"تُدار المخاطر عبر سجل المخاطر (Risk Register):\nالمخاطر القانونية والامتثال: الالتزام التام بتشريعات الجمعيات وقوانين العمل والإقامة.\nالمخاطر المالية: تطبيق سياسة احتياطي نقدي عالي السيولة يغطي التشغيل لمدة 6 أشهر على الأقل.\nمخاطر السمعة: اعتماد ميثاق إعلامي وأخلاقي صارم يحافظ على مكانة الجمعية.","url":"faq.html#f9","page":"faq.html","section":13,"group":"founders"},{"id":"b1","type":"faq","num":"س1","title":"هل تسير الإدارة التنفيذية وفق الخطط الإستراتيجية المعتمدة؟","subtitle":"","text":"يُتحقَّق من ذلك عبر تقارير متابعة ربع سنوية (Quarterly Performance Reviews) ترفعها الأمانة العامة إلى المجلس، تقارن المخرجات الميدانية بالمستهدفات الإستراتيجية المسجلة في الخطة التشغيلية لمبادرتي «ينابيع» و«منافع».","url":"faq.html#b1","page":"faq.html","section":13,"group":"board"},{"id":"b2","type":"faq","num":"س2","title":"ما مؤشرات الأداء الرئيسية (KPIs) التي يُقاس بها نجاح الإدارة التنفيذية؟","subtitle":"","text":"تتوزع المؤشرات على أربعة محاور وفق بطاقة الأداء المتوازن (Balanced Scorecard):\nالمحور المالي\nمعدل نمو الإيرادات الذاتية، ونسبة المصاريف الإدارية إلى المصاريف البرامجية.\nمحور المستفيدين\nعدد الشباب والأسر المستفيدين من التأهيل والتوظيف والورش القيمية، ومستوى رضاهم.\nمحور العمليات الداخلية\nعدد الشراكات الموقعة مع الجمعيات التركية وجمعيات الجاليات، ونسبة إنجاز المشاريع في مواعيدها.\nمحور النمو والتعلم\nنسبة الاحتفاظ بالكفاءات، وتطوير المناهج والبرامج.","url":"faq.html#b2","page":"faq.html","section":13,"group":"board"},{"id":"b3","type":"faq","num":"س3","title":"هل لدينا خطط إحلال وتعاقب وظيفي (Succession Planning) للإدارة العليا؟","subtitle":"","text":"نعم، يعتمد المجلس سياسة للتتابع القيادي تقوم على تدريب الصف الثاني في الأقسام التنفيذية الخمسة، وتوثيق جميع الأدلة الإجرائية والسياسات التشغيلية، بما يضمن استمرارية العمل وعدم ارتباطه بأشخاص بعينهم.","url":"faq.html#b3","page":"faq.html","section":13,"group":"board"},{"id":"b4","type":"faq","num":"س4","title":"هل القوائم المالية دقيقة، وتخضع لمراجعة محاسبية مستقلة وصارمة؟","subtitle":"","text":"نعم، تخضع جميع التعاملات المالية للتدقيق على مستويين:\nالرقابة الداخلية: عبر مجلس الرقابة (Denetim Kurulu) بموجب أحكام النظام الأساسي.\nالرقابة الخارجية: عبر مكاتب محاسبة قانونية معتمدة تتولى إعداد القوائم المالية والتدقيق القانوني وفق متطلبات الجهات الرسمية.","url":"faq.html#b4","page":"faq.html","section":13,"group":"board"},{"id":"b5","type":"faq","num":"س5","title":"هل تُدار التدفقات النقدية والميزانيات المعتمدة بكفاءة ودون هدر؟","subtitle":"","text":"تُدار التدفقات بموجب ميزانية تقديرية سنوية (Annual Budget) يعتمدها مجلس الإدارة، ولا يتم أي صرف إلا وفق مصفوفة الاعتماد المالي، كما يُلزم النظام المالي بعرض تحليل فروقات الميزانية (Variance Analysis) دورياً لضبط أي هدر.","url":"faq.html#b5","page":"faq.html","section":13,"group":"board"},{"id":"b6","type":"faq","num":"س6","title":"هل المؤسسة ملتزمة تماماً بالأنظمة واللوائح القانونية والضريبية بما يجنّب المجلس أي مسؤولية؟","subtitle":"","text":"تلتزم المؤسسة بأعلى مستويات الامتثال (Compliance):\nتسجيل جميع العقود والأنشطة وفق قانون الجمعيات وقانون العمل التركي.\nالتحقق من شروط الإقامة والاشتراطات القانونية لجميع الأعضاء والعاملين.\nإدارة المنشآت الاقتصادية والتجارية بحسابات ضريبية ومحاسبية مستقلة تحمي أعضاء مجلس الإدارة من أي مسؤولية شخصية.","url":"faq.html#b6","page":"faq.html","section":13,"group":"board"},{"id":"b7","type":"faq","num":"س7","title":"ما المخاطر المستجدة (السوقية، القانونية، التقنية، السمعة)؟ وكيف نُعدّ خطط الطوارئ؟","subtitle":"","text":"يراجع المجلس مصفوفة المخاطر دورياً، وعند نشوء أي خطر جديد (كتغيّر القيود القانونية أو تقلبات العملة) تُفعَّل خطط البدائل:\nالتحول الرقمي لعقد الاجتماعات والندوات عن بُعد عند الحاجة.\nتنويع سلة العملات والموارد المالية للحد من مخاطر التضخم.\nالاعتماد على بروتوكولات التعاون المشترك لخفض تكاليف التشغيل المباشر.","url":"faq.html#b7","page":"faq.html","section":13,"group":"board"},{"id":"b8","type":"faq","num":"س8","title":"كيف نضمن تطوير الخدمات وتنمية الشراكات الإستراتيجية بما يحقق الاستدامة؟","subtitle":"","text":"عبر تفعيل دور قسم الدراسات والتخطيط والاستثمار الاجتماعي وقسم التنسيق والشراكات المؤسسية، اللذين يعملان على:\nإجراء دراسات ميدانية مستمرة لاحتياجات سوق العمل والمجتمع.\nتطوير الحقائب القيمية والتنموية وتسويقها.\nعقد بروتوكولات تعاون مستمرة مع الجمعيات التركية والمؤسسات الرسمية والصناديق التنموية الدولية.","url":"faq.html#b8","page":"faq.html","section":13,"group":"board"},{"id":"welcome","type":"intro","num":"","title":"أهلاً بك في أسرة «تكامل»","subtitle":"الكتيب التعريفي الشامل للأعضاء الجدد","text":"يسعدنا انضمامك إلينا عضواً فاعلاً ومساهماً في مسيرة التنمية والبناء. إن حضورك يمثّل إضافة نوعية لجهودنا في ترسيخ القيم الأخلاقية، ودعم التمكين الاقتصادي والمجتمعي، وتحقيق الاستدامة التنموية.\nيضعك هذا الكتيب في صورة هوية الجمعية وأهدافها الإستراتيجية وفلسفة عملها ومبادراتها الرئيسية وهيكلها التنظيمي ونظامها الأساسي، لتكون على دراية كاملة بدورك ومسؤولياتك في تحقيق رؤيتنا المشتركة.","url":"index.html#welcome","page":"index.html","section":0,"group":""},{"id":"toc","type":"intro","num":"","title":"محتويات الكتيب","subtitle":"الكتيب التعريفي الشامل للأعضاء الجدد","text":"1. الهوية والمقر والأحكام العامة\n2. الرؤية والرسالة والأهداف الإستراتيجية\n3. المبادرات التنموية ومحاور العمل\n4. فلسفة العمل والأقسام التنفيذية\n5. البرنامج الزمني للتوسع الجغرافي\n6. الفئات والمؤسسات المستهدفة\n7. الحوكمة والإدارة وإجراءات العمل\n8. الأحكام المالية والاستدامة والتمويل\n9. حقوق وواجبات العضو الجديد\n10. قياس الأثر التنموي المتوقع\n11. الهيئة التأسيسية للجمعية\n12. لماذا أنضم إلى «تكامل»؟\n13. دليل الإجابات للمؤسسين ومجلس الإدارة","url":"index.html#toc","page":"index.html","section":0,"group":""},{"id":"closing","type":"intro","num":"","title":"مرحباً بك مجدداً في رحلة العطاء والتكامل","subtitle":"يداً بيد لنبني القيم ونحقق التنمية المستدامة","text":"جمعية تكامل لبناء القيم والتنمية  |  إسطنبول – الجمهورية التركية","url":"join.html","page":"join.html","section":0,"group":""}]};
